begin;
-- No committed changes, provider calls, emails, or application documents.
update public.platform_settings set maintenance=false where id;
do $$
declare conversation uuid; sender uuid; recipient uuid; message_id uuid; alert_id uuid; version_before bigint; snapshot jsonb; old_position timestamptz; booking public.bookings; payment public.payments; feedback public.reviews; enquiry uuid:=gen_random_uuid(); n integer;
begin
  select cm.conversation_id,cm.user_id,other.user_id into conversation,sender,recipient from public.conversation_members cm join public.conversation_members other on other.conversation_id=cm.conversation_id and other.user_id<>cm.user_id join public.profiles p on p.id=cm.user_id where p.demo_dataset is not null order by cm.user_id limit 1;
  if conversation is null then raise exception 'Demo conversation required'; end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',sender,'role','authenticated')::text,true);
  perform set_config('test.notification_sender',sender::text,true);perform set_config('test.notification_recipient',recipient::text,true);
  insert into public.user_notification_preferences(user_id,push_messages) values(recipient,false) on conflict(user_id) do update set push_messages=false;
  select version into version_before from public.workspace_signals where user_id=recipient;
  message_id=public.send_tutoring_message(conversation,'Rollback-only muted message');
  if exists(select 1 from public.notifications where data->>'messageId'=message_id::text) then raise exception 'Muted message created an alert'; end if;
  if (select version from public.workspace_signals where user_id=recipient)<=version_before then raise exception 'Muted conversation does not update live'; end if;
  update public.user_notification_preferences set push_messages=true where user_id=recipient;
  message_id=public.send_tutoring_message(conversation,'Rollback-only visible message');
  select id into alert_id from public.notifications where user_id=recipient and data->>'messageId'=message_id::text;
  if alert_id is null then raise exception 'Message alert missing'; end if;
  if exists(select 1 from public.notifications where user_id=sender and data->>'messageId'=message_id::text) then raise exception 'Sender notified of own message'; end if;
  update public.conversation_members set last_read_at=(select created_at from public.messages where id=message_id) where user_id=recipient and conversation_id=conversation;
  if (select read_at is null from public.notifications where id=alert_id) then raise exception 'Reading chat leaves message notification unread'; end if;
  select last_read_at into old_position from public.conversation_members where user_id=recipient and conversation_id=conversation;
  update public.conversation_members set last_read_at=old_position-interval '1 day' where user_id=recipient and conversation_id=conversation;
  if (select last_read_at from public.conversation_members where user_id=recipient and conversation_id=conversation)<>old_position then raise exception 'Read position moved backwards'; end if;
  perform set_config('test.notification_alert',alert_id::text,true);
  insert into public.notifications(user_id,kind,title,body) select sender,'application','Rollback history','Test history' from generate_series(1,105);
  snapshot=public.my_tutoring_workspace();
  if jsonb_array_length(snapshot->'notifications')<>50 or (snapshot->>'notification_unread_count')::integer<105 then raise exception 'History cap loses unread count'; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='workspace_signals') then raise exception 'Realtime publication missing'; end if;
  select * into booking from public.bookings order by id limit 1;
  insert into public.user_notification_preferences(user_id,push_booking_updates) values(booking.student_id,true),(booking.tutor_id,true) on conflict(user_id) do update set push_booking_updates=true;
  select count(*) into n from public.notifications where kind='booking' and data->>'bookingId'=booking.id::text;
  update public.bookings set special_requests=coalesce(special_requests,'')||' rollback-only' where id=booking.id;
  if (select count(*) from public.notifications where kind='booking' and data->>'bookingId'=booking.id::text)<>n then raise exception 'Unrelated booking edit creates duplicate'; end if;
  update public.bookings set status=case when status='cancelled' then 'confirmed' else 'cancelled' end where id=booking.id;
  if (select count(*) from public.notifications where kind='booking' and data->>'bookingId'=booking.id::text)<>n+2 then raise exception 'Both booking participants not notified'; end if;
  update public.bookings set status=status where id=booking.id;
  if (select count(*) from public.notifications where kind='booking' and data->>'bookingId'=booking.id::text)<>n+2 then raise exception 'Booking replay creates duplicates'; end if;
  select * into payment from public.payments order by id limit 1;
  insert into public.user_notification_preferences(user_id,push_payment_updates) values(payment.payer_id,true),(payment.payee_id,true) on conflict(user_id) do update set push_payment_updates=true;
  select count(*) into n from public.notifications where kind='payment' and data->>'paymentId'=payment.id::text;
  update public.payments set status=case when status='refunded' then 'paid' else 'refunded' end where id=payment.id;
  if (select count(*) from public.notifications where kind='payment' and data->>'paymentId'=payment.id::text)<>n+2 then raise exception 'Payment participants not notified'; end if;
  select * into feedback from public.reviews where is_published order by id limit 1;
  select count(*) into n from public.notifications where kind='review' and data->>'bookingId'=feedback.booking_id::text;
  update public.reviews set rating=case when rating=5 then 4 else 5 end where id=feedback.id;
  if (select count(*) from public.notifications where kind='review' and data->>'bookingId'=feedback.booking_id::text)<>n+1 then raise exception 'Tutor review notification missing'; end if;
  perform public.submit_contact_enquiry(enquiry,'Notification','Test','notification-flow@example.test','general','Rollback-only enquiry notification test.');
  if (select count(*) from public.notifications where data->>'enquiryId'=enquiry::text)<>(select count(*) from public.profiles where role in ('admin','superUser')) then raise exception 'Admins missing enquiry'; end if;
end; $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.notification_sender'),'role','authenticated')::text,true);
set local role authenticated;
do $$ declare target uuid:=current_setting('test.notification_alert')::uuid; before_version bigint; begin
  if exists(select 1 from public.workspace_signals where user_id<>(select auth.uid())) then raise exception 'Other workspace signal visible'; end if;
  if exists(select 1 from public.notifications where user_id<>(select auth.uid())) then raise exception 'Other notifications visible'; end if;
  begin insert into public.notifications(user_id,kind,title) values((select auth.uid()),'message','Forged');raise exception 'Notification creation allowed';exception when insufficient_privilege then null;end;
  begin update public.notifications set title='Forged';raise exception 'Notification content editable';exception when insufficient_privilege then null;end;
  begin update public.workspace_signals set version=0;raise exception 'Signal tampering allowed';exception when insufficient_privilege then null;end;
  delete from public.notifications where id=target;if found then raise exception 'Other user notification deleted'; end if;
  select version into before_version from public.workspace_signals where user_id=(select auth.uid());
  update public.notifications set read_at=clock_timestamp() where user_id=(select auth.uid()) and read_at is null;
  if exists(select 1 from public.notifications where read_at is null) then raise exception 'Read all missed older history'; end if;
  if (select version from public.workspace_signals where user_id=(select auth.uid()))<=before_version then raise exception 'Read change not signalled'; end if;
end; $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.notification_recipient'),'role','authenticated')::text,true);
set local role authenticated;
do $$ declare before_version bigint; begin
  select version into before_version from public.workspace_signals where user_id=(select auth.uid());
  delete from public.notifications where id=current_setting('test.notification_alert')::uuid;
  if not found then raise exception 'Owner cannot delete notification'; end if;
  if (select version from public.workspace_signals where user_id=(select auth.uid()))<=before_version then raise exception 'Deletion not signalled'; end if;
end; $$;
reset role;
rollback;
